#include "platform.h"
#include "gnunet_util_lib.h"
#include <assert.h>
int main(int argc,char**argv){assert(argc==2);FILE*f=fopen(argv[1],"rb");assert(f);unsigned char rfc[1024];size_t n=fread(rfc,1,sizeof(rfc),f);assert(!ferror(f));assert(!fclose(f));assert(n>=5&&n<sizeof(rfc));struct GNUNET_TUN_DnsCertRecord native={0};memcpy(&native.cert_type,rfc,2);memcpy(&native.cert_tag,rfc+2,2);native.algorithm=rfc[4];size_t total=sizeof(native)+n-5;unsigned char*input=calloc(total,1);assert(input);memcpy(input,&native,sizeof(native));memcpy(input+sizeof(native),rfc+5,n-5);size_t off=0;struct GNUNET_DNSPARSER_CertRecord*c=GNUNET_DNSPARSER_parse_cert((void*)input,total,&off);assert(c);printf("{\"type\":%u,\"key_tag\":%u,\"algorithm\":%u,\"data\":\"",c->cert_type,c->cert_tag,c->algorithm);for(size_t i=0;i<c->certificate_size;i++)printf("%02x",(unsigned char)c->certificate_data[i]);printf("\",\"native_header_size\":%zu,\"native_consumed\":%zu,\"rfc_header_size\":5,\"projection_is_field_only\":true}\n",sizeof(native),off);GNUNET_DNSPARSER_free_cert(c);free(input);return 0;}
